export function getPricing(category: string, slug: string): ProductPricing | undefined {
  const key = Object.keys(PRICING).find((k) => k === category + '/' + slug);
  if (key) return PRICING[key];
  return Object.values(PRICING).find((p) => p.slug === slug);
}